INSERT INTO public.products ("id", "name", "description", "price", "images", "stock", "category", "material", "color", "seoTitle", "metaDescription", "slug", "imageAltText", "tags", "primaryKeyword", "secondaryKeywords")
SELECT "id", "name", "description", "price", "images", "stock", "category", "material", "color", "seoTitle", "metaDescription", "slug", "imageAltText", "tags", "primaryKeyword", "secondaryKeywords" FROM source
ON CONFLICT (id) DO NOTHING;

DO $verify$
DECLARE product_count integer;
BEGIN
  SELECT count(*) INTO product_count FROM public.products;
  IF product_count <> 25 THEN
    RAISE EXCEPTION 'POSTCHECK FAILED: Expected 25 products, found %. Transaction rolled back.', product_count;
  END IF;
END
$verify$;

COMMIT;

-- Read-only final result.
SELECT count(*) AS total_products,
       count(*) FILTER (WHERE id LIKE 'CCJ-%') AS ccj_products
FROM public.products;
